<?php $titulo_pagina='Candidatar-se';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';verificarAutenticacao();if(($_SESSION['tipo_usuario']??'')==='empresa')redirecionar('/vagas.php');$vaga=(int)($_GET['vaga']??$_POST['vaga_id']??0);$stmt=$mysqli->prepare('SELECT v.*,e.nome_fantasia FROM vagas v JOIN empresas e ON e.id=v.empresa_id WHERE v.id=? AND v.ativa=1');$stmt->bind_param('i',$vaga);$stmt->execute();$dados=$stmt->get_result()->fetch_assoc();$stmt=$mysqli->prepare('SELECT id FROM curriculos WHERE usuario_id=?');$stmt->bind_param('i',$_SESSION['usuario_id']);$stmt->execute();$cv=$stmt->get_result()->fetch_assoc();if(!$cv){mensagem_erro('Cadastre seu currículo antes de se candidatar.');redirecionar('/dashboard/curriculo.php');}if($_SERVER['REQUEST_METHOD']==='POST'&&validar_csrf($_POST['csrf_token']??'')){$msg=trim($_POST['mensagem']??'');$stmt=$mysqli->prepare('INSERT IGNORE INTO candidaturas(vaga_id,curriculo_id,mensagem) VALUES(?,?,?)');$stmt->bind_param('iis',$vaga,$cv['id'],$msg);$stmt->execute();mensagem_sucesso('Candidatura enviada.');redirecionar('/vagas.php');}require_once __DIR__.'/includes/header.php';?><div class="container"><div class="form-container"><h1><?php echo sanitizar($dados['titulo']); ?></h1><p><?php echo sanitizar($dados['nome_fantasia']); ?></p><p><?php echo nl2br(sanitizar($dados['descricao'])); ?></p><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="vaga_id" value="<?php echo $vaga; ?>"><div class="form-group"><label>Mensagem para a empresa</label><textarea name="mensagem"></textarea></div><button class="btn">Enviar candidatura</button></form></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
